class AnimController {
  final int durationMs;
  double value = 0.0;
  bool isAnimating = false;

  AnimController(this.durationMs);

  void start() {
    isAnimating = true;
  }

  void stop() {
    isAnimating = false;
  }

  void reset() {
    value = 0.0;
    isAnimating = false;
  }

  void tick(int elapsedMs) {
    if (!isAnimating) return;
    value += elapsedMs / durationMs;
    if (value >= 1.0) {
      value = 1.0;
      isAnimating = false;
    }
  }

  int progress() {
    return (value * 100).toInt();
  }

  String describe() {
    final status = isAnimating ? 'running' : (value >= 1.0 ? 'completed' : 'idle');
    return 'Anim($value, $status)';
  }
}

void main() {
  final anim = AnimController(1000);
  anim.start();

  anim.tick(300);
  print('After 300ms: ${anim.describe()}, progress=${anim.progress()}%');

  anim.tick(300);
  print('After 600ms: ${anim.describe()}, progress=${anim.progress()}%');

  anim.tick(500);
  print('After 1100ms: ${anim.describe()}, progress=${anim.progress()}%');
  print('Animating: ${anim.isAnimating}');

  anim.reset();
  print('After reset: ${anim.describe()}');
}

