class Tween<T extends num> {
  final T begin;
  final T end;

  Tween(this.begin, this.end);

  T lerp(double t) {
    final diff = end - begin;
    if (diff is int) {
      return (begin + (diff * t).round()) as T;
    }
    return (begin + (diff * t)) as T;
  }

  T transform(double t) {
    final clamped = t.clamp(0.0, 1.0);
    return lerp(clamped);
  }

  Tween<T> reverse() {
    return Tween(end, begin);
  }

  Tween<T> chain(Tween<T> other) {
    return Tween(begin, other.end);
  }

  String describe() {
    return 'Tween($begin → $end)';
  }
}

void main() {
  final tween = Tween(0, 100);
  print(tween.describe());
  print('t=0: ${tween.lerp(0.0)}');
  print('t=0.5: ${tween.lerp(0.5)}');
  print('t=1: ${tween.lerp(1.0)}');
  print('t=1.5 clamped: ${tween.transform(1.5)}');
  print('t=-0.5 clamped: ${tween.transform(-0.5)}');
  print('Reversed: ${tween.reverse().describe()}');
  print('Chained: ${tween.chain(Tween(100, 200)).describe()}');
}

