class AnimSequence {
  final List<int> durationsMs;
  int currentPhase = 0;
  double phaseProgress = 0.0;

  AnimSequence(this.durationsMs);

  bool get isComplete {
    return currentPhase >= durationsMs.length - 1 &&
        phaseProgress >= 1.0;
  }

  void tick(int elapsedMs) {
    if (isComplete) return;
    if (durationsMs.isEmpty) return;

    final duration = durationsMs[currentPhase];
    phaseProgress += elapsedMs / duration;

    while (phaseProgress >= 1.0 && currentPhase < durationsMs.length - 1) {
      phaseProgress -= 1.0;
      currentPhase++;
      final nextDuration = durationsMs[currentPhase];
      phaseProgress = phaseProgress * (duration / nextDuration);
    }

    if (phaseProgress >= 1.0) {
      phaseProgress = 1.0;
    }
  }

  int totalDurationMs() {
    return durationsMs.fold(0, (sum, d) => sum + d);
  }

  double overallProgress() {
    int elapsed = 0;
    for (int i = 0; i < currentPhase; i++) {
      elapsed += durationsMs[i];
    }
    elapsed += (phaseProgress * durationsMs[currentPhase]).toInt();
    return elapsed / totalDurationMs();
  }

  String describe() {
    final total = durationsMs.length;
    final pp = (phaseProgress * 100).toInt();
    final op = (overallProgress() * 100).toInt();
    return 'Seq(phase ${currentPhase + 1}/$total, $pp%, overall $op%)';
  }

  void reset() {
    currentPhase = 0;
    phaseProgress = 0.0;
  }
}

void main() {
  final seq = AnimSequence([500, 300, 200]);
  print('Total: ${seq.totalDurationMs()}ms');

  seq.tick(250);
  print(seq.describe());

  seq.tick(300);
  print(seq.describe());

  seq.tick(200);
  print(seq.describe());
  print('Complete: ${seq.isComplete}');

  seq.reset();
  print('After reset: ${seq.describe()}');
}

