class EasingCurve {
  final String name;

  EasingCurve(this.name);

  double apply(double t) {
    switch (name) {
      case 'linear':
        return t;
      case 'easeIn':
        return t * t;
      case 'easeOut':
        return 1 - (1 - t) * (1 - t);
      case 'easeInOut':
        if (t < 0.5) return 2 * t * t;
        return 1 - (-2 * t + 2) * (-2 * t + 2) / 2;
      default:
        return t;
    }
  }

  List<double> sample(int steps) {
    return List.generate(steps, (i) => apply(i / (steps - 1)));
  }

  double speed(double t) {
    switch (name) {
      case 'linear':
        return 1.0;
      case 'easeIn':
        return 2 * t;
      case 'easeOut':
        return 2 * (1 - t);
      case 'easeInOut':
        if (t < 0.5) return 4 * t;
        return -4 * (1 - t);
      default:
        return 1.0;
    }
  }

  String describe() => 'EasingCurve($name)';
}

void main() {
  for (final name in ['linear', 'easeIn', 'easeOut', 'easeInOut']) {
    final curve = EasingCurve(name);
    print('${curve.describe()}: apply(0.5)=${curve.apply(0.5)}, speed(0.5)=${curve.speed(0.5)}');
    print('  sample(5)=${curve.sample(5)}');
  }
}

