import 'dart:math';

class SpringSimulation {
  final double stiffness;
  final double damping;
  final double mass;

  SpringSimulation(this.stiffness, this.damping, {this.mass = 1.0});

  double position(double t) {
    if (stiffness <= 0) return 0.0;

    final omega = sqrt(stiffness / mass);
    final zeta = damping / (2 * sqrt(stiffness * mass));

    if (zeta < 1) {
      final wd = omega * sqrt(1 - zeta * zeta);
      return exp(-zeta * omega * t) * cos(wd * t);
    } else {
      return 1 - exp(-omega * t) * (1 + omega * t);
    }
  }

  double velocity(double t) {
    final dt = 0.001;
    return (position(t + dt) - position(t)) / dt;
  }

  bool get isSettled {
    return (position(10.0) - 1.0).abs() < 0.01;
  }

  String get dampingType {
    if (stiffness <= 0) return 'unknown';
    final zeta = damping / (2 * sqrt(stiffness * mass));
    if (zeta < 1) return 'underdamped';
    if (zeta == 1) return 'critically_damped';
    return 'overdamped';
  }

  String describe() => 'Spring(k=$stiffness, c=$damping, m=$mass, $dampingType)';
}

void main() {
  final spring = SpringSimulation(100.0, 10.0);
  print(spring.describe());
  print('Position at 0: ${spring.position(0.0)}');
  print('Position at 0.5: ${spring.position(0.5)}');
  print('Velocity at 0: ${spring.velocity(0.0)}');
  print('Settled: ${spring.isSettled}');

  final overdamped = SpringSimulation(100.0, 50.0);
  print(overdamped.describe());
}
